/**
 * FloatingReactions — réactions emoji qui remontent l'écran (V6.B). Couche de
 * RENDU souveraine : l'audience envoie un emoji (companion mobile → transport
 * WS, chantier séparé), l'écran projeté fait remonter l'emoji façon Twitch/
 * Instagram Live. Ici : le hook de gestion (expiration auto) + la couche visuelle.
 *
 * `prefers-reduced-motion` → l'emoji apparaît brièvement puis disparaît sans
 * translation (garde règle 43). Chaque emoji s'auto-retire après `ttlMs`.
 */
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { useCallback, useRef, useState } from "react";

import { px } from "@/shared/design-tokens/scale";


export interface FloatingReaction {
  id: number;
  emoji: string;
  /** Position horizontale de départ (%). */
  x: number;
}

/**
 * Gère la file des réactions actives, avec expiration automatique. `push(emoji)`
 * ajoute une réaction ; elle se retire seule après `ttlMs`. Ids déterministes
 * (compteur) pour un rendu et des tests stables.
 */
export function useFloatingReactions(ttlMs = 3200) {
  const [reactions, setReactions] = useState<FloatingReaction[]>([]);
  const idRef = useRef(0);

  const push = useCallback(
    (emoji: string) => {
      const id = idRef.current++;
      const x = 8 + Math.random() * 84;
      setReactions((rs) => [...rs, { id, emoji, x }]);
      window.setTimeout(
        () => setReactions((rs) => rs.filter((r) => r.id !== id)),
        ttlMs,
      );
    },
    [ttlMs],
  );

  return { reactions, push };
}

interface FloatingReactionsLayerProps {
  reactions: FloatingReaction[];
}

export function FloatingReactionsLayer({
  reactions,
}: FloatingReactionsLayerProps) {
  const noMotion = useReducedMotion() === true;
  return (
    <div
      aria-hidden
      style={{
        position: "fixed",
        inset: 0,
        pointerEvents: "none",
        zIndex: 55,
        overflow: "hidden",
      }}
    >
      <AnimatePresence>
        {reactions.map((r) => (
          <motion.span
            key={r.id}
            initial={noMotion ? { opacity: 0 } : { opacity: 0, y: 0 }}
            animate={
              noMotion
                ? { opacity: 1 }
                : { opacity: [0, 1, 1, 0], y: -320, x: [0, 18, -12, 6] }
            }
            exit={{ opacity: 0 }}
            transition={{ duration: noMotion ? 0.2 : 3.0, ease: "easeOut" }}
            style={{
              position: "absolute",
              bottom: px(80),
              left: `${r.x}%`,
              fontSize: px(40),
            }}
          >
            {r.emoji}
          </motion.span>
        ))}
      </AnimatePresence>
    </div>
  );
}
