/**
 * MagicMove — le « Magic Move » de Keynote : un élément marqué du MÊME
 * `flipId` dans deux vues successives se DÉPLACE et se transforme de l'une à
 * l'autre, au lieu de disparaître puis de réapparaître.
 *
 * Pourquoi GSAP Flip et pas le `layoutId` de framer : une scène de
 * présentation est remontée par `key` → l'élément est DÉMONTÉ, ce que
 * `layoutId` ne survit pas. Flip capture un instantané au démontage (l'élément
 * est encore dans le DOM pendant le nettoyage), le garde hors de React, et
 * l'anime depuis l'ancienne position quand le nouvel élément monte. Mouvement
 * réduit → pas de vol (apparition simple). Durée de vie courte de l'instantané,
 * pour qu'un vol fantôme ne parte pas quand les vues ne s'enchaînent pas.
 *
 * Rejoint le moteur d'animation le 2026-10-14 (il vivait dans la bibliothèque
 * « wahou » du moteur de présentation) : socle GSAP unique, durée et courbe en
 * jetons.
 */
import { useGSAP } from "@gsap/react";
import { useRef } from "react";
import type { ReactNode } from "react";

import { duration } from "@/shared/design-tokens/motion";

import { COURBE_KEYNOTE, Flip, gsap, inscrireGsap } from "./gsap";
import { mouvementReduit } from "./mouvement-reduit";

type FlipState = ReturnType<typeof Flip.getState>;

const instantanes = new Map<string, { state: FlipState; ts: number }>();

function garder(id: string, state: FlipState): void {
  instantanes.set(id, { state, ts: gsap.ticker.time });
}

function reprendre(id: string, ageMaxS = 1.2): FlipState | null {
  const entree = instantanes.get(id);
  if (!entree) return null;
  instantanes.delete(id);
  return gsap.ticker.time - entree.ts <= ageMaxS ? entree.state : null;
}

interface MagicMoveProps {
  /** Identifiant partagé entre les deux vues (l'élément qui « vole »). */
  flipId: string;
  children: ReactNode;
  className?: string;
}

export function MagicMove({ flipId, children, className }: MagicMoveProps) {
  const ref = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      inscrireGsap();
      const el = ref.current;
      if (!el) return;
      const avant = reprendre(flipId);
      if (avant && !mouvementReduit()) {
        Flip.from(avant, {
          targets: el,
          absolute: true,
          duration: duration.slow,
          ease: COURBE_KEYNOTE,
        });
      }
      return () => {
        if (ref.current) garder(flipId, Flip.getState(ref.current));
      };
    },
    { scope: ref },
  );

  return (
    <div ref={ref} data-flip-id={flipId} className={className}>
      {children}
    </div>
  );
}
