/**
 * Card3D — LA profondeur d'un moment signature, en transformations CSS (zéro
 * three.js) : une capture d'application ou une maquette qui arrive en pivotant
 * jusqu'à son angle de repos, avec ombre portée et perspective. À DOSER : une
 * fois par présentation.
 *
 * Entrée unique au montage, jamais de boucle (une présentation se raconte au
 * clic, sans ambiance qui tourne pendant la parole). Mouvement réduit → la
 * carte se pose directement à l'angle de repos, sans pivot.
 *
 * Rejoint le moteur d'animation le 2026-10-14 (elle vivait dans la bibliothèque
 * « wahou » du moteur de présentation) : sa durée et sa courbe sont des jetons,
 * son ombre la nuit de la marque et non un bleu recopié en dur.
 */
import { motion, useReducedMotion } from "framer-motion";
import type { ReactNode } from "react";

import { color, withOpacity } from "@/shared/design-tokens/color";
import { duration, ease } from "@/shared/design-tokens/motion";
import { num, shadow } from "@/shared/design-tokens/scale";

interface Card3DProps {
  children: ReactNode;
  /** Angle Y de repos (°). Défaut −18 (légère perspective de trois-quarts). */
  restRotateY?: number;
  /** Angle X de repos (°). Défaut 6. */
  restRotateX?: number;
  /** Profondeur de la perspective (px). Défaut 1400. */
  perspective?: number;
  className?: string;
}

export function Card3D({
  children,
  restRotateY = -18,
  restRotateX = 6,
  perspective = 1400,
  className,
}: Card3DProps) {
  const reduit = useReducedMotion() === true;

  return (
    <div
      className={className}
      style={{ perspective: `${perspective}px`, transformStyle: "preserve-3d" }}
    >
      <motion.div
        initial={
          reduit
            ? false
            : { rotateY: restRotateY - 55, rotateX: restRotateX + 10, opacity: 0, y: 40 }
        }
        animate={{ rotateY: restRotateY, rotateX: restRotateX, opacity: 1, y: 0 }}
        transition={{ duration: reduit ? 0 : duration.cinematic, ease: ease.keynote }}
        style={{
          transformStyle: "preserve-3d",
          borderRadius: num(22),
          overflow: "hidden",
          boxShadow: shadow(
            `0 50px 100px -25px ${withOpacity(color.primaryBlack, 0.45)}, 0 0 0 1px ${withOpacity(color.primaryBlack, 0.06)}`,
          ),
        }}
      >
        {children}
      </motion.div>
    </div>
  );
}
