/**
 * QuizScene — quiz gamifié mis en scène (V6.B). Une question, des propositions
 * en cartes, puis RÉVÉLATION de la bonne réponse au fragment : la bonne carte
 * passe en vert avec un ✓, les autres s'estompent. Souverain, intégré à la
 * charte du deck. Option : afficher les votes reçus (companion salle).
 *
 * `prefers-reduced-motion` → transitions coupées (états finaux directs). Texte
 * toujours lisible (règle 27) ; la bonne réponse a un libellé accessible.
 */
import { motion, useReducedMotion } from "framer-motion";
import { useContext } from "react";

import { color, withOpacity } from "@/shared/design-tokens/color";
import { px } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";

import { KineticText } from "@/shared/animations/KineticText";

import { FragmentStepContext } from "./fragments";

export interface QuizOption {
  label: string;
  correct?: boolean;
  /** Votes reçus (optionnel — companion salle). */
  votes?: number;
}

interface QuizSceneProps {
  question: string;
  options: QuizOption[];
  /** ≥1 = réponse révélée. Défaut : lit le `FragmentStepContext`. */
  active?: number;
  className?: string;
}

export function QuizScene({
  question,
  options,
  active,
  className,
}: QuizSceneProps) {
  const ctxStep = useContext(FragmentStepContext);
  const step = active ?? (ctxStep === Number.MAX_SAFE_INTEGER ? 1 : ctxStep);
  const revealed = step >= 1;
  const noMotion = useReducedMotion() === true;

  return (
    <div className={className}>
      <KineticText as="h2" split="words">
        {question}
      </KineticText>

      <div
        role="list"
        style={{
          display: "grid",
          gap: px(12),
          gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))",
          marginTop: px(20),
        }}
      >
        {options.map((o) => {
          const isCorrect = Boolean(o.correct);
          const highlight = revealed && isCorrect;
          const dimmed = revealed && !isCorrect;
          return (
            <motion.div
              key={o.label}
              role="listitem"
              aria-label={highlight ? `${o.label} — bonne réponse` : o.label}
              initial={false}
              animate={{ opacity: dimmed ? 0.5 : 1 }}
              transition={{ duration: noMotion ? 0 : 0.35 }}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                gap: px(12),
                padding: `${px(16)} ${px(20)}`,
                borderRadius: radius.md,
                border: `${px(2)} solid ${
                  highlight ? color.success : withOpacity(color.primary, 0.2)
                }`,
                background: highlight
                  ? withOpacity(color.secondary, 0.12)
                  : "transparent",
                fontSize: px(19),
                fontWeight: 600,
              }}
            >
              <span>{o.label}</span>
              {highlight ? (
                <span
                  aria-hidden
                  style={{ color: color.success, fontWeight: 800 }}
                >
                  ✓
                </span>
              ) : typeof o.votes === "number" ? (
                <span aria-hidden style={{ opacity: 0.6 }}>
                  {o.votes}
                </span>
              ) : null}
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}
