/**
 * Source de verite unique pour formatter des cents en chaine FR.
 * Les autres helpers (`currency.ts:formatCentsToEuros`, `pdf-helpers.ts:
 * formatCentsAsEuros`) sont desormais des thin wrappers vers `formatCents`
 * pour garantir un format coherent partout dans l'app.
 */
interface FormatCentsOptions {
  /**
   * Si true, n'affiche pas les décimales (montants entiers, KPI, dashboards).
   * @example formatCents(12345, { compact: true }) → "123 €"
   *
   * ⚠️ ARRONDIT (`Math.round`), il ne tronque pas l'affichage : 1 250,50 €
   * devient « 1 251 € ». Le critère n'est donc pas la place disponible, c'est
   * la NATURE du montant.
   *
   *   ✅ légitime — une ESTIMATION ou une PROPOSITION : fourchette de tarif
   *      publique, suggestion de prix, montant estimé d'un suivi de temps,
   *      métrique d'un tableau de bord. Une proposition d'avocat ne s'annonce
   *      pas à deux décimales (décision assumée, `RequestResponseCard`).
   *
   *   ❌ interdit — une somme DUE ou DÉJÀ ENCAISSÉE : bouton de paiement,
   *      montant à régler, revenus encaissés, facture, échéance. L'utilisateur
   *      la rapproche de son relevé bancaire, et un écart de 50 centimes au
   *      moment de payer coûte plus que la place gagnée.
   *
   * Deux défauts trouvés le 2026-07-31 en capturant : le bouton « Payer X »
   * d'une provision, et les revenus instant (dont les montants réels sont
   * 51,40 · 141,40 · 191,40) affichés à l'euro — la somme des lignes ne
   * retombait pas sur le total.
   */
  compact?: boolean;
  /**
   * @deprecated NO-OP depuis 2026-07-12 (cycle C1 `facturation-paiements`) : le
   * DEFAUT produit deja ce format. Conserve pour ne pas casser les 13 appelants
   * qui le passaient explicitement — ne plus l'ajouter, et le retirer au fil de
   * l'eau.
   */
  intl?: boolean;
}

/**
 * Format an amount in cents to a localized French currency string.
 * @example formatCents(12345) → "123,45 €"
 * @example formatCents(12345, { compact: true }) → "123 €"
 * @example formatCents(123456789, { intl: true }) → "1 234 567,89 €"
 */
export function formatCents(
  cents: number,
  options: FormatCentsOptions = {},
): string {
  // Defensive — `null`/`NaN` venant d'API ou de calculs. On repasse par la
  // meme fabrique Intl que les montants normaux : sinon le zero aurait un espace
  // different avant l'euro, et toute comparaison de chaine echouerait.
  if (cents == null || Number.isNaN(cents)) {
    return formatCents(0, options);
  }
  if (options.compact) {
    return Math.round(cents / 100).toLocaleString("fr-FR", {
      style: "currency",
      currency: "EUR",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    });
  }
  // DEFAUT CORRIGE — cycle C1 `facturation-paiements` (2026-07-12).
  //
  // Le chemin par defaut faisait `(cents/100).toFixed(2).replace('.', ',') + ' EUR'` :
  // EXACTEMENT l'anti-pattern que `agent-rules/localization-fr.md` interdit —
  // aucun separateur de milliers, et un espace SECABLE (U+0020) avant l'euro (le
  // montant pouvait donc se couper en fin de ligne). Le format correct etait
  // relegue derriere `{ intl: true }`, donc oublie 86 fois sur 100. Constate en
  // runtime sur le hub Paiements : « 1680,00 » au lieu de « 1 680,00 ».
  //
  // `options.intl` n'est plus lu : le defaut EST desormais le format canonique.
  return (cents / 100).toLocaleString("fr-FR", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

/**
 * Nombre localisé FR — virgule décimale + espace des milliers.
 * LE helper canonique pour tout chiffre NON monétaire affiché à l'utilisateur
 * (une note « 4,2 », un ratio « 3,5 », un taux « 12,7 »). Sans lui, un
 * `.toFixed(1)` ou un `<Statistic value={x}/>` Ant produit « 4.2 » (point
 * anglais) — le défaut de localisation le plus fréquent du repo (règle 48).
 *
 * @example frNumber(4.25, 1) → "4,3"   frNumber(1680) → "1 680"
 */
export function frNumber(value: number, decimals = 0): string {
  if (value == null || Number.isNaN(value)) return frNumber(0, decimals);
  return value.toLocaleString("fr-FR", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

/**
 * `formatter` prêt à brancher sur un `<Statistic>` Ant pour qu'il rende en FR
 * (Ant formate en anglais par défaut : « 4.2 », « 1,680 »). Passer la précision
 * voulue. Usage : `<Statistic value={x} formatter={frStatFormatter(1)} />`.
 */
export function frStatFormatter(decimals = 0) {
  return (value: string | number) => frNumber(Number(value), decimals);
}

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Returns true if the string looks like a UUID (technical ID that should not be shown to users).
 */
export function isUuid(value: string | undefined | null): boolean {
  return !!value && UUID_RE.test(value);
}

/**
 * Returns the value only if it's a non-empty, non-UUID string suitable for display.
 * Returns undefined otherwise — safe to use in JSX conditionals.
 */
export function safeLabel(
  value: string | undefined | null,
): string | undefined {
  return value && !UUID_RE.test(value) ? value : undefined;
}

/**
 * Initiales (2 max, majuscules) d'un nom complet, pour un avatar.
 * `"Sophie Martin"` → `"SM"` · `"SCI Bellevue"` → `"SB"` · vide → `"?"`.
 */
export function getInitials(name: string | undefined | null): string {
  return (
    (name ?? "")
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part.charAt(0).toUpperCase())
      .join("") || "?"
  );
}

/**
 * Pluriel FR via Intl.PluralRules (regle 48 localisation).
 * `one` = 0/1, `other` = 2+.
 *
 * Cause #1 de bug visuel : `${count} dossiers` qui affiche `1 dossiers`.
 *
 * Le zero est au SINGULIER en francais et `Intl.PluralRules` le sait :
 * `select(0) === 'one'`, donc « 0 dossier ». Ce commentaire affirmait l'inverse
 * (« casse pour 0, devrait etre pluriel ») — mesure et corrige le 2026-07-26,
 * en meme temps que localization-fr.md qui portait la meme erreur.
 *
 * Ce que le pattern `count > 1 ? 's' : ''` casse vraiment : il duplique la
 * regle a chaque site, se desynchronise du nombre affiche, et rate les
 * irreguliers (creneau -> creneaux). Use `pluralizeFr(count, 'dossier', 'dossiers')`.
 */
const __pluralRulesFr =
  typeof Intl !== "undefined" && typeof Intl.PluralRules === "function"
    ? new Intl.PluralRules("fr-FR")
    : null;

export function pluralizeFr(
  count: number,
  singular: string,
  plural: string,
): string {
  // V7 guard : NaN/Infinity ne doivent jamais arriver via React mais on
  // securise (helper UI, ne doit JAMAIS throw).
  //
  // ⚠ ET UNE CHAÎNE NON PLUS (corrigé 2026-07-30). `Number.isFinite` ne
  // convertit RIEN — contrairement au `isFinite` global — donc
  // `Number.isFinite("1")` vaut `false` et le garde renvoyait le PLURIEL :
  // « 1 dossiers en cours » s'affichait à l'avocat qui tentait d'archiver un
  // contact. Le cas venait d'une capture de regex, typée `string`, que
  // TypeScript signalait sans que personne puisse lancer le typecheck. Avec
  // 1198 appels dans le dépôt, mieux vaut convertir ici une fois que compter
  // sur chacun d'eux : une valeur numérique écrite en toutes lettres reste un
  // nombre pour un lecteur, elle doit l'être pour l'accord aussi.
  //
  // On ne convertit QUE les chaînes, délibérément. `Number(null)` vaut 0, donc
  // convertir tout ferait accorder « null » au SINGULIER — un changement de
  // comportement gratuit sur un cas dégénéré, que le test de ce garde a
  // attrapé. Une chaîne numérique a un sens, `null` n'en a pas.
  const n = typeof count === 'string' ? Number(count) : count;
  if (!Number.isFinite(n)) return plural;
  if (__pluralRulesFr) {
    return __pluralRulesFr.select(n) === "one" ? singular : plural;
  }
  // Fallback navigateur tres ancien : approximation FR (one = 0/1)
  return n <= 1 ? singular : plural;
}

/**
 * Masque le préfixe `demo_{env}_{uid8}_` dans les emails démo affichés en UI.
 *
 * Audit Raoul Delpech 2026-05-12 M001/B068 — les emails contacts demo sont stockés
 * sous la forme `demo_local_abc12345_marie.client@example.com` pour
 * permettre purge propre + matching pool prewarming (cf demo-prewarming
 * service ligne 1299-1310 LIKE pattern). Mais ce préfixe ne devrait JAMAIS
 * être visible à l'utilisateur dans l'UI.
 *
 * Cette fonction masque le préfixe en gardant tout après le 2e underscore.
 * Pour les emails non-démo (sans préfixe), retourne l'email inchangé.
 *
 * @example
 * formatDisplayEmail('demo_local_a1b2c3d4_marie@example.com')
 *   // → 'marie@example.com'
 * formatDisplayEmail('jean.dupont@gmail.com')
 *   // → 'jean.dupont@gmail.com'
 */
export function formatDisplayEmail(email: string | null | undefined): string {
  if (!email) return "";
  // Pattern : demo_{env}_{uid_or_uuid_short}_ → 3 segments avant le contenu
  // Match : demo_xxx_xxx_ (xxx = chars sans underscore)
  const match = email.match(/^demo_[^_]+_[^_]+_(.+)$/);
  if (match) return match[1];
  return email;
}

/**
 * Le compteur d'un badge de notification, plafonné.
 *
 * SOURCE UNIQUE. La même règle vivait en TROIS exemplaires — messagerie, cloche
 * et header mobile — chacun avec sa propre copie de `if (count > 99)`. Trois
 * copies d'une décision produit (« à partir de quand cesse-t-on de compter ? »)
 * dérivent tôt ou tard : il suffit qu'une seule surface change de seuil pour que
 * l'application dise deux vérités sur la même boîte de réception.
 *
 * POURQUOI 99 ET PAS 9. Le plafond est une perte d'information assumée, et son
 * seuil se paie en largeur : « 99+ » fait trois caractères, donc un badge
 * sensiblement plus large qu'un chiffre seul. Ancré par son CENTRE sur le coin de
 * l'icône (cf. les badges du header), ce débordement est propre — il l'était
 * beaucoup moins quand le badge grandissait vers l'intérieur et mangeait son
 * propre glyphe. 99 est conservé parce qu'il distingue « beaucoup » de
 * « énormément », là où « 9+ » réduirait 12 messages et 400 messages au même
 * signal.
 */
export function formatBadgeCount(count: number): string {
  if (count > 99) return "99+";
  return count.toString();
}

/**
 * Libellé d'onglet ou de filtre suivi de son compteur — SAUF quand il vaut zéro.
 *
 * Un zéro affiché n'informe pas, il occupe : « Validés (0) · Envoyés (0) »
 * alignait deux chiffres nuls à côté du seul qui appelait une action
 * (« À rédiger (10) »), et « 0 Envoyés » en vert dans un bandeau de santé
 * dilue de la même façon. La doctrine avait déjà été appliquée au cockpit
 * (changelog « plus aucun décompte à zéro ») puis, le 2026-08-01, à la
 * Transcription et au Catalogue — trois surfaces, trois corrections inline :
 * d'où ce helper, pour que la règle vive à UN endroit (règle 87, fédérer).
 *
 * Le libellé et sa porte restent TOUJOURS : un onglet vide se clique, son état
 * vide est légitime et souvent pédagogique. C'est le chiffre nul qu'on retire,
 * jamais l'accès.
 *
 * @example
 *   labelWithCount("Actes", 0)  // "Actes"
 *   labelWithCount("Actes", 3)  // "Actes (3)"
 */
export function labelWithCount(
  label: string,
  count: number | null | undefined,
): string {
  return typeof count === "number" && count > 0 ? `${label} (${count})` : label;
}

/**
 * Une prose libre ramenée à la taille d'une balise `meta`.
 *
 * MESURE DE PRODUCTION DU 2026-08-22 : sur les fiches d'avocats RÉELS qui
 * portent une biographie, **33 sur 37 dépassent 160 signes**, la plus longue
 * en fait **2 404**. Cette prose partait telle quelle dans
 * `<meta name="description">` ET dans `og:description` — or Google coupe vers
 * 155 signes, et les messageries reprennent la balise mot pour mot. Le
 * résultat était un extrait tranché au milieu d'un mot, sur la surface la
 * plus publique du produit.
 *
 * Trois soins, dans cet ordre :
 *  1. les blancs se normalisent — une bio saisie sur plusieurs paragraphes
 *     produit sinon une balise à retours à la ligne ;
 *  2. on coupe à la fin d'une PHRASE quand il en existe une assez tardive
 *     (au-delà de 55 % de la place), parce qu'un extrait qui se termine par
 *     un point se lit comme un texte écrit pour ça ;
 *  3. sinon on coupe au dernier espace et on pose une vraie ellipse.
 *
 * Le seuil des 55 % évite le pire cas : une bio qui commence par « Avocat. »
 * ne doit pas rendre un extrait de sept signes.
 *
 * @example
 *   resumeMeta("Avocat au barreau de Lyon. Vingt ans de pratique.", 40)
 *   // "Avocat au barreau de Lyon."
 */
export function resumeMeta(texte: string, max = 160): string {
  const propre = texte.replace(/\s+/g, " ").trim();
  if (propre.length <= max) return propre;

  const fenetre = propre.slice(0, max);
  const finDePhrase = Math.max(
    fenetre.lastIndexOf(". "),
    fenetre.lastIndexOf("! "),
    fenetre.lastIndexOf("? "),
  );
  if (finDePhrase >= max * 0.55) return fenetre.slice(0, finDePhrase + 1);

  const dernierEspace = propre.slice(0, max - 1).lastIndexOf(" ");
  const coupe = dernierEspace > 0 ? dernierEspace : max - 1;
  return propre.slice(0, coupe).replace(/[,;:.!?\s]+$/, "") + "…";
}

/**
 * Deux qualifiants qui se recouvrent n'informent qu'une fois.
 *
 * Vu au dark de Recettes le 2026-09-04 : « Consultation · Consultation
 * ponctuelle » sur six lignes visibles sur sept. L'objet d'un paiement et son
 * type se recouvrent souvent — l'un porte le mot générique, l'autre sa
 * précision. Les afficher tous les deux occupe une ligne pour dire une chose,
 * et c'est exactement la redondance que la fusion des colonnes devait
 * supprimer : la reproduire dans la cellule aurait été la déplacer.
 *
 * Quand l'un CONTIENT l'autre (comparaison insensible à la casse ET aux
 * accents), seul le plus long reste. Sinon les deux sont gardés :
 * « Consultation · Consult. dossier » ne se recouvrent pas au sens strict, et
 * l'abréviation porte une information que le mot seul n'a pas.
 *
 * Volontairement conservateur : effacer une nuance est pire que laisser passer
 * une redondance de plus.
 */
export function dedoublonnerQualifiants(
  valeurs: (string | null | undefined)[],
): string[] {
  const nets = valeurs
    .map((v) => v?.trim())
    .filter((v): v is string => Boolean(v));

  const pliee = (s: string) =>
    s
      .toLocaleLowerCase('fr-FR')
      .normalize('NFD')
      .replace(/\p{Diacritic}/gu, '');

  return nets.filter(
    (valeur, i) =>
      !nets.some(
        (autre, j) =>
          j !== i &&
          // Le plus long gagne ; à longueur égale, le premier reste.
          (autre.length > valeur.length ||
            (autre.length === valeur.length && j < i)) &&
          pliee(autre).includes(pliee(valeur)),
      ),
  );
}

/**
 * Énumère en français : « A, B et C » — jamais « A et B et C ».
 *
 * Le français ne met la conjonction QUE devant le dernier terme ; les autres se
 * séparent par des virgules. `join(" et ")` est donc juste à deux éléments et
 * faux au-delà — et c'est exactement l'angle mort qu'il crée : on l'écrit en
 * pensant au cas courant (deux), le code compile, le rendu se lit bien, et la
 * phrase ne devient fautive que le jour où une troisième valeur arrive.
 *
 * Repéré le 2026-09-04 sur les origines d'argent en échec : les sorties en ont
 * TROIS (dépenses saisies, retenues Stripe, frais Juris-Power) et le solde en
 * agrège CINQ, les deux côtés de la soustraction réunis. « vos dépenses saisies
 * et les retenues Stripe et les frais Juris-Power » attendait la panne qui
 * ferait tomber trois sources à la fois.
 *
 * `Intl.ListFormat` ferait ce travail, mais rend le « oxford comma » en anglais
 * et n'est pas configurable sur la liaison : ici on veut pouvoir dire « ou »
 * pour des OPTIONS (« visioconférence, téléphone ou présentiel ») et « et »
 * pour un CUMUL. Le choix de la liaison porte du sens, il ne se devine pas.
 *
 * @param liaison la conjonction devant le dernier terme — « et » par défaut
 *                (un cumul), « ou » pour des options qui s'excluent.
 */
export function enumererFr(
  mots: readonly (string | null | undefined)[],
  liaison: 'et' | 'ou' = 'et',
): string {
  const nets = mots
    .map((m) => m?.trim())
    .filter((m): m is string => Boolean(m));

  if (nets.length === 0) return '';
  if (nets.length === 1) return nets[0];
  return `${nets.slice(0, -1).join(', ')} ${liaison} ${nets[nets.length - 1]}`;
}

/**
 * La taille d'un fichier, en français.
 *
 * ── QUINZE IMPLÉMENTATIONS, ET AU MOINS TROIS CONVENTIONS ───────────────────
 *
 * Mesuré le 2026-09-11 en regardant le drive au pixel : `formatFileSize`,
 * `formatBytes` et leurs variantes vivaient dans QUINZE fichiers du front, avec
 * des unités qui ne s'accordaient pas — `B/Ko/Mo/Go` ici, `B/KB/MB/GB` là.
 *
 * Deux fautes se lisaient dans le même écran :
 *
 *     en-tête   « 12 documents — 1.4 Ko »   ← point anglais (règle 48)
 *     lignes    « 45 B »                    ← unité anglaise à côté de « Ko »
 *
 * « B » n'est pas français. L'octet s'écrit **o**, et la série est o · Ko · Mo ·
 * Go. Mélanger les deux dans un même tableau donne à l'avocat deux systèmes
 * d'unités pour une seule grandeur.
 *
 * Le séparateur décimal passe par `frNumber`, qui est déjà LE helper canonique
 * du dépôt pour tout chiffre non monétaire.
 *
 * ── « ON N'A PAS PU MESURER » N'EST PAS « ZÉRO OCTET » ──────────────────────
 *
 * Le premier jet rendait « 0 o » pour `null`. C'est la faute exacte que
 * `useStorageUsage` avait déjà corrigée après un audit, et dont son commentaire
 * dit la conséquence : « un avocat qui lit "0 o utilisés" croit son espace vide
 * alors qu'on n'a pas pu regarder, sur la jauge même qui sert à prévenir la
 * saturation ». Une absence de mesure se DIT — elle ne se déguise pas en
 * mesure valant zéro.
 *
 * `useStorageUsage` n'est d'ailleurs PAS branché sur ce hub, et c'est délibéré :
 * il porte deux décimales sur les gigaoctets, parce qu'une jauge de quota doit
 * montrer qu'elle bouge. Aplatir cette finesse aurait été une régression
 * déguisée en uniformisation.
 *
 * @example formatTailleFichier(0)       → "0 o"
 *          formatTailleFichier(45)      → "45 o"
 *          formatTailleFichier(1434)    → "1,4 Ko"
 *          formatTailleFichier(1048576) → "1 Mo"
 *          formatTailleFichier(null)    → "—"
 */
export function formatTailleFichier(
  octets: number | null | undefined,
): string {
  if (octets == null || !Number.isFinite(octets)) return '—';
  if (octets <= 0) return '0 o';

  const UNITES = ['o', 'Ko', 'Mo', 'Go', 'To'] as const;
  const rang = Math.min(
    Math.floor(Math.log(octets) / Math.log(1024)),
    UNITES.length - 1,
  );
  const valeur = octets / Math.pow(1024, rang);

  // Pas de décimale sur les octets : « 45,0 o » ne dit rien de plus que « 45 o ».
  // Pas de décimale non plus sur un entier rond, pour la même raison.
  const decimales = rang === 0 || Number.isInteger(valeur) ? 0 : 1;
  return `${frNumber(valeur, decimales)} ${UNITES[rang]}`;
}
