/**
 * LiveResultsScene — rendu SOUVERAIN des résultats d'un sondage salle (V6.B).
 * Les résultats (votés via Particify/ARSnova auto-hébergé, ou toute source)
 * sont affichés AVEC nos primitives — jamais un iframe tiers projeté : la
 * question en KineticText, des barres qui se remplissent aux proportions
 * réelles, le compte de votes qui roule (CountUp). Intégré à la charte
 * du deck, pas un corps étranger.
 *
 * Piloté au fragment (barres révélées) ; `prefers-reduced-motion` → barres
 * pleines sans animation. Texte toujours lisible (règle 27).
 */
import { motion, useReducedMotion } from "framer-motion";
import { pluralizeFr } from '@/shared/utils/format';
import { useContext, useMemo } from "react";

import { color } from "@/shared/design-tokens/color";
import { px } from "@/shared/design-tokens/scale";

import { CountUp } from "@/shared/animations/CountUp";
import { KineticText } from "@/shared/animations/KineticText";

import { FragmentStepContext } from "./fragments";

export interface PollOption {
  label: string;
  votes: number;
}

interface LiveResultsSceneProps {
  question: string;
  options: PollOption[];
  /** Nombre de barres révélées (piloté par le fragment). Défaut : toutes. */
  active?: number;
  accent?: string;
  className?: string;
}

export function LiveResultsScene({
  question,
  options,
  active,
  accent = color.primary,
  className,
}: LiveResultsSceneProps) {
  const ctxStep = useContext(FragmentStepContext);
  const revealed =
    active ?? (ctxStep === Number.MAX_SAFE_INTEGER ? options.length : ctxStep);
  const total = useMemo(
    () => options.reduce((s, o) => s + Math.max(0, o.votes), 0),
    [options],
  );
  const noMotion = useReducedMotion() === true;

  return (
    <div className={className}>
      <KineticText as="h2" split="words">
        {question}
      </KineticText>

      <p style={{ margin: `${px(6)} 0 ${px(20)}`, fontWeight: 700 }}>
        <CountUp value={total} triggerOnScroll={false} style={{ fontVariantNumeric: "tabular-nums" }} /> {pluralizeFr(total, 'vote', 'votes')}
      </p>

      <div role="list" style={{ display: "grid", gap: px(14) }}>
        {options.map((o, i) => {
          const pct = total > 0 ? Math.round((o.votes / total) * 100) : 0;
          const shown = i < revealed;
          return (
            <div key={o.label} role="listitem">
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  fontSize: px(18),
                  fontWeight: 600,
                  marginBottom: px(6),
                }}
              >
                <span>{o.label}</span>
                <span aria-hidden style={{ color: accent, fontWeight: 800 }}>
                  {pct} %
                </span>
              </div>
              <div
                style={{
                  height: px(14),
                  borderRadius: px(7),
                  background: color.blackAlpha08,
                  overflow: "hidden",
                }}
              >
                <motion.div
                  initial={noMotion ? false : { width: 0 }}
                  animate={{ width: shown ? `${pct}%` : 0 }}
                  transition={{
                    duration: noMotion ? 0 : 0.7,
                    ease: "easeOut",
                    delay: noMotion ? 0 : i * 0.08,
                  }}
                  style={{ height: "100%", background: accent }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
