/**
 * MorphShape — une forme SVG devient une autre (GSAP MorphSVG). Le geste
 * keynote rare et fort : document → € → ✓ payé. À doser (une ou deux fois par
 * présentation). Mouvement réduit → bascule instantanée.
 *
 * Rejoint le moteur d'animation le 2026-10-14 (il vivait dans la bibliothèque
 * « wahou » du moteur de présentation) : socle GSAP unique, durée et courbe en
 * jetons.
 */
import { useGSAP } from "@gsap/react";
import { useRef } from "react";
import type { SVGProps } from "react";

import { duration as durees } from "@/shared/design-tokens/motion";

import { COURBE_KEYNOTE, gsap, inscrireGsap } from "./gsap";
import { mouvementReduit } from "./mouvement-reduit";

interface MorphShapeProps extends Omit<SVGProps<SVGPathElement>, "d"> {
  /** Les états successifs du tracé (liste de `d`). */
  shapes: string[];
  /** Index de la forme active (piloté par l'appelant : un fragment, un état). */
  active: number;
  /** Durée du passage (s). Défaut : la durée « cinématique » des jetons. */
  duration?: number;
}

export function MorphShape({
  shapes,
  active,
  duration = durees.cinematic,
  ...pathProps
}: MorphShapeProps) {
  const ref = useRef<SVGPathElement>(null);
  const clamped = Math.max(0, Math.min(shapes.length - 1, active));

  useGSAP(
    () => {
      inscrireGsap();
      const el = ref.current;
      if (!el) return;
      const target = shapes[clamped];
      if (mouvementReduit()) {
        gsap.set(el, { attr: { d: target } });
        return;
      }
      gsap.to(el, { morphSVG: target, duration, ease: COURBE_KEYNOTE });
    },
    { dependencies: [clamped], scope: ref },
  );

  return <path ref={ref} d={shapes[0]} {...pathProps} />;
}
