/**
 * KineticText — un titre révélé ligne, mot ou caractère sous masque (GSAP
 * SplitText, réécrit en 2025 : accessible, accents français gérés).
 *
 * LA révélation de texte du moteur d'animation depuis le 2026-10-14 : elle
 * vivait dans la bibliothèque « wahou » du moteur de présentation, et le moteur
 * d'animation portait la sienne, `SplitTextReveal`, sans un seul appelant —
 * celle-ci, qui sert, est restée ; l'autre est retirée.
 *
 * Le texte reste TOUJOURS dans le DOM (lisible, sélectionnable, lu par un
 * lecteur d'écran) — l'animation ne fait que le révéler. Mouvement réduit, ou
 * un environnement sans mise en page (test) → aucun découpage, le texte
 * s'affiche tel quel (règles 43 et 27). Anime une fois, au montage : une scène
 * de présentation remontée par clé la rejoue en entrant.
 */
import { useGSAP } from "@gsap/react";
import { createElement, useRef } from "react";
import type { ReactNode } from "react";

import { duration, stagger as cadence } from "@/shared/design-tokens/motion";

import { COURBE_KEYNOTE, SplitText, gsap, inscrireGsap } from "./gsap";
import { mouvementReduit } from "./mouvement-reduit";

type SplitKind = "lines" | "words" | "chars";

interface KineticTextProps {
  children: ReactNode;
  /** Balise rendue (h1/h2/p/span…). Défaut span. */
  as?: keyof HTMLElementTagNameMap;
  /** Granularité du découpage. Défaut "lines". */
  split?: SplitKind;
  /** Décalage entre éléments (s). Défaut : la cadence normale des jetons. */
  stagger?: number;
  /** Direction d'entrée. Défaut "up". */
  from?: "up" | "down";
  /** Délai avant l'animation (s). */
  delay?: number;
  className?: string;
}

export function KineticText({
  children,
  as = "span",
  split = "lines",
  stagger = cadence.normal,
  from = "up",
  delay = 0,
  className,
}: KineticTextProps) {
  const ref = useRef<HTMLElement>(null);
  // RGAA (V6.F) : SplitText fragmente le texte en spans (lu caractère/mot par
  // un lecteur d'écran). Quand le contenu est une chaîne, on expose le texte
  // COMPLET en aria-label pour qu'il soit lu d'un bloc. Contenu riche (ReactNode)
  // → on laisse le DOM tel quel (déjà lisible).
  const ariaLabel = typeof children === "string" ? children : undefined;

  useGSAP(
    () => {
      inscrireGsap();
      const el = ref.current;
      if (!el || mouvementReduit()) return;
      let st: SplitText | null = null;
      try {
        st = SplitText.create(el, { type: split, mask: split });
      } catch {
        return; // pas de mise en page (jsdom) → texte brut, pas d'animation
      }
      const targets =
        split === "words" ? st.words : split === "chars" ? st.chars : st.lines;
      gsap.from(targets, {
        yPercent: from === "up" ? 110 : -110,
        opacity: 0,
        stagger,
        delay,
        duration: duration.cinematic,
        ease: COURBE_KEYNOTE,
      });
      return () => st?.revert();
    },
    { scope: ref },
  );

  return createElement(
    as,
    { ref, className, "aria-label": ariaLabel },
    children,
  );
}
