/**
 * CountUp — Animated number counter
 *
 * Decompte de 0 (ou start) vers une valeur cible avec easing.
 * Se declenche au scroll (IntersectionObserver) ou immediatement.
 *
 * LE compteur du moteur d'animation : depuis le 2026-10-14
 * (presentation-engine V7), il porte les formats monetaire et pourcentage du
 * moteur de presentation, dont les deux compteurs (`count-up.tsx`,
 * `RollingNumber`) sont retires. Dans une planche, `triggerOnScroll={false}` :
 * il part au montage de la scene.
 *
 * Usage :
 *   <CountUp value={12500} suffix=" EUR" duration={1.8} />
 *   <CountUp value={93.1} suffix="%" decimals={1} />
 *   <CountUp value={75} format="currency" triggerOnScroll={false} />   // 75 €
 *   <CountUp value={95} format="percent" triggerOnScroll={false} />    // 95 %
 */
import { useEffect, useRef, useState, useCallback } from 'react';
import { useReducedMotion } from 'framer-motion';

interface CountUpProps {
  /** Target value */
  value: number;
  /** Starting value (default 0) */
  start?: number;
  /** Animation duration in seconds */
  duration?: number;
  /** Number of decimal places */
  decimals?: number;
  /** Text before the number */
  prefix?: string;
  /** Text after the number */
  suffix?: string;
  /** Locale for number formatting (default fr-FR) */
  locale?: string;
  /**
   * Le format du nombre : `number` (defaut), `currency` (monnaie, euro par
   * defaut) ou `percent` (la valeur est en points : 95 rend « 95 % »).
   */
  format?: 'number' | 'currency' | 'percent';
  /** La devise du format `currency` (defaut EUR). */
  currency?: string;
  /** Trigger animation on scroll into view (default true) */
  triggerOnScroll?: boolean;
  /** Thousands separator (e.g. ' ' for fr-FR, ',' for en-US) */
  separator?: string;
  /** Custom className */
  className?: string;
  /** Custom style */
  style?: React.CSSProperties;
}

/**
 * La deceleration exponentielle, gardee ici plutot que dans la couche scene
 * (`scene/courbes.ts`) : le compteur sert treize ecrans, et l'importer de la
 * ajouterait un fichier au graphe de chacun (budget de fichiers par ecran).
 */
function easeOutExpo(t: number): number {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

export function CountUp({
  value,
  start = 0,
  duration = 1.6,
  decimals = 0,
  prefix = '',
  suffix = '',
  locale = 'fr-FR',
  format = 'number',
  currency = 'EUR',
  triggerOnScroll = true,
  className,
  style,
}: CountUpProps) {
  const [displayValue, setDisplayValue] = useState(start);
  const [hasStarted, setHasStarted] = useState(!triggerOnScroll);
  const ref = useRef<HTMLSpanElement>(null);
  const rafRef = useRef<number>(0);
  const prefersReducedMotion = useReducedMotion();

  // Intersection observer for scroll trigger
  useEffect(() => {
    if (!triggerOnScroll || hasStarted || !ref.current) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setHasStarted(true);
          observer.disconnect();
        }
      },
      { threshold: 0.3 },
    );

    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [triggerOnScroll, hasStarted]);

  // Animation loop
  useEffect(() => {
    if (!hasStarted) return;

    if (prefersReducedMotion) {
      setDisplayValue(value);
      return;
    }

    /*
     * L'ORIGINE DU TEMPS EST LA PREMIÈRE IMAGE, pas l'appel de l'effet
     * (2026-09-28, banc du socle des auvents).
     *
     * `performance.now()` pris ici et l'horodatage que `requestAnimationFrame`
     * passe à `animate` ne viennent pas du même instant — le second est le
     * DÉBUT de l'image, qui peut le précéder. L'écart peut donc être négatif,
     * et rien ne bornait la progression par le bas : `easeOutExpo` d'un
     * nombre négatif part vers moins l'infini. Au navigateur l'écart tient en
     * une fraction d'image (non observé à l'écran) ; sous jsdom, dont les deux
     * horloges n'ont pas la même origine, il est énorme — le compte y rendait
     * « -93 011 % », mesuré au banc. Le temps se mesure donc sur UNE horloge,
     * celle des images, et la progression reste dans [0, 1].
     */
    let startTime: number | null = null;
    const durationMs = duration * 1000;
    const range = value - start;

    const animate = (now: number) => {
      if (startTime === null) startTime = now;
      const elapsed = now - startTime;
      const progress = Math.min(Math.max(elapsed / durationMs, 0), 1);
      const easedProgress = easeOutExpo(progress);
      const current = start + range * easedProgress;

      setDisplayValue(current);

      if (progress < 1) {
        rafRef.current = requestAnimationFrame(animate);
      }
    };

    rafRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(rafRef.current);
  }, [hasStarted, value, start, duration, prefersReducedMotion]);

  const formatNumber = useCallback(
    (n: number) => {
      const chiffres = { minimumFractionDigits: decimals, maximumFractionDigits: decimals };
      if (format === 'currency') {
        return new Intl.NumberFormat(locale, { ...chiffres, style: 'currency', currency }).format(n);
      }
      if (format === 'percent') {
        return new Intl.NumberFormat(locale, { ...chiffres, style: 'percent' }).format(n / 100);
      }
      return new Intl.NumberFormat(locale, chiffres).format(n);
    },
    [locale, decimals, format, currency],
  );

  return (
    <span ref={ref} className={className} style={style}>
      {prefix}{formatNumber(displayValue)}{suffix}
    </span>
  );
}
