/**
 * DataWheel — roue/donut data-driven aux proportions RÉELLES (bibliothèque
 * wahou). Souverain zéro-npm : le calcul d'arc (équivalent d3.arc/d3.pie) est
 * réimplémenté en ~30 lignes de géométrie SVG, pas de dépendance d3.
 *
 * Chaque secteur reflète la vraie valeur (pas une géométrie tracée à l'œil) et
 * apparaît au fragment (piloté par le moteur). `prefers-reduced-motion` → tous
 * les secteurs visibles d'emblée. À utiliser pour : répartition, entonnoir,
 * roue de services, parts de marché.
 */
import { motion, useReducedMotion } from "framer-motion";
import { useContext } from "react";

import { duration, ease } from "@/shared/design-tokens/motion";

import { FragmentStepContext } from "../fragments";

export interface WheelSegment {
  value: number;
  color: string;
  label?: string;
}

/** Point sur un cercle : angle 0 = haut (12 h), sens horaire. */
function polar(cx: number, cy: number, r: number, a: number): [number, number] {
  return [cx + r * Math.sin(a), cy - r * Math.cos(a)];
}

/** Path d'un secteur de donut entre deux angles (radians). */
function arc(
  cx: number,
  cy: number,
  innerR: number,
  outerR: number,
  a0: number,
  a1: number,
): string {
  const [xo0, yo0] = polar(cx, cy, outerR, a0);
  const [xo1, yo1] = polar(cx, cy, outerR, a1);
  const [xi1, yi1] = polar(cx, cy, innerR, a1);
  const [xi0, yi0] = polar(cx, cy, innerR, a0);
  const large = a1 - a0 > Math.PI ? 1 : 0;
  return `M${xo0} ${yo0} A${outerR} ${outerR} 0 ${large} 1 ${xo1} ${yo1} L${xi1} ${yi1} A${innerR} ${innerR} 0 ${large} 0 ${xi0} ${yi0} Z`;
}

interface DataWheelProps {
  segments: WheelSegment[];
  /** Diamètre (px). Défaut 320. */
  size?: number;
  /** Rayon intérieur / extérieur (0 = camembert plein, 0.6 = donut fin). Défaut 0.58. */
  innerRatio?: number;
  /** Espace entre secteurs (radians). Défaut 0.03. */
  gap?: number;
  /**
   * Nombre de secteurs révélés (piloté par le fragment). Défaut : lit le
   * `FragmentStepContext` du moteur (en showroom = tous révélés).
   */
  active?: number;
  className?: string;
}

export function DataWheel({
  segments,
  size = 320,
  innerRatio = 0.58,
  gap = 0.03,
  active,
  className,
}: DataWheelProps) {
  const ctxStep = useContext(FragmentStepContext);
  const revealed =
    active ??
    (ctxStep === Number.MAX_SAFE_INTEGER ? segments.length : ctxStep);

  const total = segments.reduce((s, seg) => s + Math.max(0, seg.value), 0) || 1;
  const cx = size / 2;
  const cy = size / 2;
  const outerR = size / 2 - 4;
  const innerR = outerR * innerRatio;

  let cursor = 0;
  const arcs = segments.map((seg, i) => {
    const a0 = (cursor / total) * Math.PI * 2 + gap / 2;
    cursor += Math.max(0, seg.value);
    const a1 = (cursor / total) * Math.PI * 2 - gap / 2;
    return { d: arc(cx, cy, innerR, outerR, a0, a1), color: seg.color, i };
  });

  const noMotion = useReducedMotion() === true;

  return (
    <svg
      viewBox={`0 0 ${size} ${size}`}
      width={size}
      height={size}
      className={className}
      role="img"
    >
      {arcs.map((a) => {
        const shown = a.i < revealed;
        return (
          <motion.path
            key={a.i}
            d={a.d}
            fill={a.color}
            initial={noMotion ? false : { opacity: 0, scale: 0.6 }}
            animate={{ opacity: shown ? 1 : 0.12, scale: shown ? 1 : 0.94 }}
            transition={{ duration: noMotion ? 0 : duration.slow, ease: ease.keynote }}
            style={{ transformOrigin: `${cx}px ${cy}px` }}
          />
        );
      })}
    </svg>
  );
}
