/**
 * StaggerReveal — révèle les enfants en CASCADE, au montage. Chaque enfant
 * direct est enveloppé d'office : aucune pièce à poser autour de chacun.
 *
 * La cascade de `StaggerList` attend que la liste entre dans la vue et veut un
 * `StaggerItem` autour de chaque élément ; celle-ci part dès le montage et
 * enveloppe seule — ce qu'il faut à une scène de présentation, et à une phrase
 * dont les segments s'énoncent l'un après l'autre (le héros public de
 * Juris-IA). Elle vivait dans la bibliothèque « wahou » du moteur de
 * présentation ; elle rejoint le moteur d'animation le 2026-10-14, ses
 * durées et sa courbe devenues des jetons.
 *
 * Mouvement réduit → tous les enfants visibles d'emblée, sans mouvement
 * (règle 43), et le réglage est suivi en direct.
 */
import { motion, useReducedMotion } from "framer-motion";
import { Children, createElement } from "react";
import type { ReactNode } from "react";

import { duration, ease, stagger as cadence } from "@/shared/design-tokens/motion";

interface StaggerRevealProps {
  children: ReactNode;
  /** Décalage entre enfants (s). Défaut : la cadence normale des jetons. */
  stagger?: number;
  /** Délai avant le premier (s). Défaut 0. */
  delay?: number;
  /** Direction d'entrée. Défaut "up". */
  from?: "up" | "down" | "left" | "right" | "fade";
  /** Balise conteneur. Défaut "div". */
  as?: keyof HTMLElementTagNameMap;
  className?: string;
}

const OFFSETS: Record<string, { x?: number; y?: number }> = {
  up: { y: 18 },
  down: { y: -18 },
  left: { x: 18 },
  right: { x: -18 },
  fade: {},
};

export function StaggerReveal({
  children,
  stagger = cadence.normal,
  delay = 0,
  from = "up",
  as = "div",
  className,
}: StaggerRevealProps) {
  const reduit = useReducedMotion() === true;
  if (reduit) {
    return createElement(as, { className }, children);
  }

  const offset = OFFSETS[from] ?? OFFSETS.up;
  const container = {
    hidden: {},
    show: { transition: { staggerChildren: stagger, delayChildren: delay } },
  };
  const item = {
    hidden: { opacity: 0, ...offset },
    show: {
      opacity: 1,
      x: 0,
      y: 0,
      transition: { duration: duration.slow, ease: ease.keynote },
    },
  };

  const MotionTag = motion[as as "div"];
  return (
    <MotionTag
      className={className}
      variants={container}
      initial="hidden"
      animate="show"
    >
      {Children.map(children, (child, i) => (
        <motion.div key={i} variants={item}>
          {child}
        </motion.div>
      ))}
    </MotionTag>
  );
}
