/**
 * LegalDiff — deux versions d'un texte de loi qui MORPHENT mot à mot (V6.D).
 * Le cas d'usage juridique de la bibliothèque wahou : montrer l'AVANT / APRÈS
 * d'un article réformé. Au fragment, les mots retirés se barrent et s'estompent,
 * les mots ajoutés apparaissent surlignés — la réforme se lit d'un coup d'œil.
 *
 * Souverain zéro-npm : diff mot à mot maison (LCS ~25 lignes), rendu framer.
 * `prefers-reduced-motion` → état APRÈS directement (barré/surligné, sans
 * animation). Le texte reste TOUJOURS lisible (règle 27).
 */
import { motion, useReducedMotion } from "framer-motion";
import { useContext, useMemo } from "react";

import { color } from "@/shared/design-tokens/color";
import { duration } from "@/shared/design-tokens/motion";

import { FragmentStepContext } from "../fragments";

export type DiffKind = "same" | "add" | "del";
export interface DiffToken {
  text: string;
  kind: DiffKind;
}

/**
 * Diff mot à mot par plus longue sous-séquence commune (LCS). Les blancs sont
 * conservés comme jetons (l'espacement d'origine est préservé). Pur, testable.
 */
export function diffWords(before: string, after: string): DiffToken[] {
  const a = before.split(/(\s+)/);
  const b = after.split(/(\s+)/);
  const m = a.length;
  const n = b.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () =>
    new Array<number>(n + 1).fill(0),
  );
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const out: DiffToken[] = [];
  let i = 0;
  let j = 0;
  while (i < m && j < n) {
    if (a[i] === b[j]) {
      out.push({ text: a[i], kind: "same" });
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      out.push({ text: a[i], kind: "del" });
      i++;
    } else {
      out.push({ text: b[j], kind: "add" });
      j++;
    }
  }
  while (i < m) out.push({ text: a[i++], kind: "del" });
  while (j < n) out.push({ text: b[j++], kind: "add" });
  return out;
}

interface LegalDiffProps {
  /** Version d'origine de l'article. */
  before: string;
  /** Version réformée. */
  after: string;
  /**
   * Phase pilotée : 0 = avant (texte d'origine), ≥1 = après (réforme révélée).
   * Défaut : lit le `FragmentStepContext` (showroom = après).
   */
  active?: number;
  addColor?: string;
  delColor?: string;
  className?: string;
}

export function LegalDiff({
  before,
  after,
  active,
  addColor = color.secondaryStrong,
  delColor = color.gray600,
  className,
}: LegalDiffProps) {
  const tokens = useMemo(() => diffWords(before, after), [before, after]);
  const ctxStep = useContext(FragmentStepContext);
  const step = active ?? (ctxStep === Number.MAX_SAFE_INTEGER ? 1 : ctxStep);
  const isAfter = step >= 1;
  const noMotion = useReducedMotion() === true;

  return (
    <p className={className} style={{ lineHeight: 1.7 }}>
      {tokens.map((t, k) => {
        if (t.kind === "same") return <span key={k}>{t.text}</span>;
        // Contact direct del↔add (le mot remplacé et son remplaçant) : l'espace
        // d'origine est un jeton « same » placé APRÈS le couple, donc les deux
        // mots se collent (« sept »+« quatorze »). On rétablit une respiration
        // dès que deux glyphes non-blancs s'abutent, quel que soit le kind.
        const prev = tokens[k - 1];
        const gap =
          prev && !/\s$/.test(prev.text) && !/^\s/.test(t.text)
            ? { marginInlineStart: "0.28em" }
            : undefined;
        if (t.kind === "del") {
          return (
            <motion.span
              key={k}
              initial={noMotion ? false : { opacity: 1 }}
              animate={{
                opacity: isAfter ? 0.55 : 1,
                textDecorationLine: isAfter ? "line-through" : "none",
              }}
              transition={{ duration: noMotion ? 0 : duration.slow }}
              style={{ color: isAfter ? delColor : "inherit", ...gap }}
            >
              {t.text}
            </motion.span>
          );
        }
        // add
        return (
          <motion.span
            key={k}
            initial={noMotion ? false : { opacity: 0 }}
            animate={{ opacity: isAfter ? 1 : 0 }}
            transition={{
              duration: noMotion ? 0 : duration.slow,
              delay: noMotion ? 0 : 0.2,
            }}
            style={{ color: addColor, fontWeight: 700, ...gap }}
          >
            {t.text}
          </motion.span>
        );
      })}
    </p>
  );
}
