/**
 * DrawPath / TravelToken — des schémas SVG VIVANTS (GSAP DrawSVG + MotionPath).
 * À placer DANS un <svg> fourni par l'appelant.
 *
 * DrawPath : un tracé qui se dessine au trait (là où une astuce CSS de
 * `stroke-dashoffset` n'offre pas le contrôle sous le pixel). TravelToken : un
 * jeton (la « facture ») qui parcourt EXACTEMENT un tracé, orienté selon lui.
 * Mouvement réduit → l'état final (tracé complet, jeton à l'arrivée).
 *
 * Rejoignent le moteur d'animation le 2026-10-14 (ils vivaient dans la
 * bibliothèque « wahou » du moteur de présentation) : socle GSAP unique, durée
 * et courbe en jetons.
 */
import { useGSAP } from "@gsap/react";
import { useRef } from "react";
import type { ReactNode, SVGProps } from "react";

import { duration } from "@/shared/design-tokens/motion";

import { COURBE_KEYNOTE, gsap, inscrireGsap } from "./gsap";
import { mouvementReduit } from "./mouvement-reduit";

interface DrawPathProps extends SVGProps<SVGPathElement> {
  /** Durée du tracé (s). Défaut : la durée « cinématique » des jetons. */
  drawDuration?: number;
  delay?: number;
}

export function DrawPath({ drawDuration = duration.cinematic, delay = 0, ...pathProps }: DrawPathProps) {
  const ref = useRef<SVGPathElement>(null);
  useGSAP(
    () => {
      inscrireGsap();
      if (!ref.current || mouvementReduit()) return;
      gsap.from(ref.current, {
        drawSVG: "0%",
        duration: drawDuration,
        delay,
        ease: COURBE_KEYNOTE,
      });
    },
    { scope: ref },
  );
  return <path ref={ref} {...pathProps} />;
}

interface TravelTokenProps {
  /** Identifiant du tracé à suivre (dans le même <svg>). */
  pathId: string;
  /** Contenu du jeton (cercle, icône, groupe). */
  children: ReactNode;
  /** Durée du trajet (s). Défaut 1,6 : un trajet se lit, il ne se devine pas. */
  travelDuration?: number;
  delay?: number;
  /** Oriente le jeton le long du tracé. Défaut true. */
  autoRotate?: boolean;
  /** Répéter (boucle) — déconseillé pendant une parole, défaut 0 (un seul passage). */
  repeat?: number;
}

export function TravelToken({
  pathId,
  children,
  travelDuration = 1.6,
  delay = 0,
  autoRotate = true,
  repeat = 0,
}: TravelTokenProps) {
  const ref = useRef<SVGGElement>(null);
  useGSAP(
    () => {
      inscrireGsap();
      const el = ref.current;
      const path = el?.ownerSVGElement?.querySelector<SVGPathElement>(`#${pathId}`);
      if (!el || !path) return;
      try {
        if (mouvementReduit()) {
          // Le jeton se pose à l'arrivée, sans trajet.
          gsap.set(el, { motionPath: { path, align: path, alignOrigin: [0.5, 0.5], start: 1, end: 1 } });
          return;
        }
        gsap.fromTo(
          el,
          { motionPath: { path, align: path, alignOrigin: [0.5, 0.5], autoRotate, start: 0, end: 0 } },
          {
            motionPath: { path, align: path, alignOrigin: [0.5, 0.5], autoRotate, start: 0, end: 1 },
            duration: travelDuration,
            delay,
            repeat,
            ease: "power1.inOut",
          },
        );
      } catch {
        // Pas de mise en page SVG (jsdom : getCTM absent) → pas d'animation, jeton immobile.
      }
    },
    { scope: ref },
  );
  return <g ref={ref}>{children}</g>;
}
