/**
 * Timeline — axe chronologique dont l'axe se trace et les jalons apparaissent
 * en cascade (bibliothèque wahou). Le pendant TEMPOREL de DataWheel (spatial) :
 * pour « les échéances », un calendrier de réforme, une roadmap.
 *
 * Souverain zéro-npm (SVG + framer). L'axe se dessine gauche→droite, chaque
 * jalon pop décalé. `prefers-reduced-motion` → axe complet + jalons visibles,
 * sans animation. Un jalon `emphasis` est mis en avant (couleur d'accent).
 */
import { motion, useReducedMotion } from "framer-motion";
import { useContext } from "react";

import { color as couleurs } from "@/shared/design-tokens/color";
import { duration, stagger } from "@/shared/design-tokens/motion";

import { FragmentStepContext } from "../fragments";

export interface Milestone {
  date: string;
  label: string;
  /** Jalon mis en avant (l'échéance qui presse). */
  emphasis?: boolean;
}

interface TimelineProps {
  milestones: Milestone[];
  /** Largeur (px). Défaut 900. */
  width?: number;
  color?: string;
  accent?: string;
  /**
   * Nombre de jalons révélés (piloté par le fragment). Défaut : lit le
   * `FragmentStepContext` (showroom = tous).
   */
  active?: number;
  className?: string;
}

export function Timeline({
  milestones,
  width = 900,
  color = couleurs.primaryBlack,
  accent = couleurs.secondaryStrong,
  active,
  className,
}: TimelineProps) {
  const ctxStep = useContext(FragmentStepContext);
  const revealed =
    active ??
    (ctxStep === Number.MAX_SAFE_INTEGER ? milestones.length : ctxStep);
  const noMotion = useReducedMotion() === true;

  const height = 150;
  const axisY = 70;
  const padX = 70;
  const span = width - padX * 2;
  const last = milestones.length - 1;
  const n = Math.max(1, milestones.length - 1);

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      style={{ maxWidth: width }}
      className={className}
      role="img"
    >
      {/* Axe qui se trace */}
      <motion.line
        x1={padX}
        y1={axisY}
        x2={width - padX}
        y2={axisY}
        stroke={color}
        strokeWidth={3}
        strokeLinecap="round"
        initial={noMotion ? false : { pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: noMotion ? 0 : duration.cinematic, ease: "easeInOut" }}
      />
      {milestones.map((m, i) => {
        const x = milestones.length === 1 ? width / 2 : padX + (span * i) / n;
        const shown = i < revealed;
        const c = m.emphasis ? accent : color;
        // Jalons extrêmes : label aligné vers l'INTÉRIEUR (jamais coupé par le
        // bord) ; intermédiaires centrés (vérif visuelle 2026-07-05).
        const anchor = i === 0 ? "start" : i === last ? "end" : "middle";
        return (
          <motion.g
            key={m.date + i}
            initial={noMotion ? false : { opacity: 0, y: 10 }}
            animate={{ opacity: shown ? 1 : 0.15, y: shown ? 0 : 10 }}
            transition={{
              duration: noMotion ? 0 : duration.medium,
              delay: noMotion ? 0 : 0.6 + i * stagger.slow,
            }}
          >
            <circle cx={x} cy={axisY} r={m.emphasis ? 11 : 7} fill={c} />
            <text
              x={x}
              y={axisY - 22}
              textAnchor={anchor}
              fontSize={19}
              fontWeight={800}
              fill={c}
            >
              {m.date}
            </text>
            <text
              x={x}
              y={axisY + 34}
              textAnchor={anchor}
              fontSize={15}
              fontWeight={600}
              fill={color}
            >
              {m.label}
            </text>
          </motion.g>
        );
      })}
    </svg>
  );
}
